group CdaEimpfSubstanceAdministrationToFhirImmunization(source cda_substanceAdministration: SubstanceAdministration, target fhir_immunization: Immunization, target fhir_bundle: Bundle) {
  // substanceAdministration/id -> Immunization.identifier 
  cda_substanceAdministration.id -> fhir_immunization.identifier;

  // substanceAdministration/text

  // substanceAdministration/statusCode -> Immunization.status
  cda_substanceAdministration.statusCode -> fhir_immunization.status; 

  // substanceAdministration/effectiveTime -> Immunization.occurrenceDateTime
  cda_substanceAdministration.effectiveTime as cda_substanceAdministration_effectiveTime -> 
    fhir_immunization.occurrence = create('dateTime') as fhir_immunization_occurrence then TSDateTime(cda_substanceAdministration_effectiveTime, fhir_immunization_occurrence) 
    "CdaEffectiveTimeToFhirOccurrenceDateTime";
  
  // substanceAdministration/routeCode -> Immunization.route
  cda_substanceAdministration.routeCode where ($this.nullFlavor.exists().not()) -> fhir_immunization.route;

  // substanceAdministration/doseQuantity -> AtApsImmunization.doseQuantity
  cda_substanceAdministration.doseQuantity as cda_substanceAdministration_doseQuantity where ($this.nullFlavor.exists().not()) -> 
    fhir_immunization.doseQuantity as fhir_immunization_doseQuantity then
    PQQuantity(cda_substanceAdministration_doseQuantity, fhir_immunization_doseQuantity)
    "CdaDoseQuantityToFhirDoseQuantity";

  // substanceAdministration/consumable
  cda_substanceAdministration.consumable as cda_consumable then {
    // substanceAdministration/consumable/manufacturedProduct
    cda_consumable.manufacturedProduct as cda_manufacturedProduct then {
      // substanceAdministration/consumable/manufacturedProduct/id
      // TODO

      // substanceAdministration/consumable/manufacturedProduct/manufacturedMaterial
      cda_manufacturedProduct.manufacturedMaterial as cda_manufacturedMaterial then {
        /*ToDo: 
          - Group refractor code (change manufacturedProduct to manufacturedMaterial)
            Gruppe die manuFacturedProduct zu FHIR Immunization Mapped.
            cda_manufacturedProduct then CdaManufacturedMaterialToFhirImmunizationMedication(cda_manufacturedProduct, fhir_immunization, fhir_bundle);
        */

        // substanceAdministration/consumable/manufacturedProduct/manufacturedMaterial/code -> Immunization.vaccineCode
        // Vaccine Product nicht angegeben - 1.2.40.0.34.6.0.11.9.31
        //
        // TODO: nullFlavor-extension vs. dataAbsentReason-extension vs. nullFlavor-coding
        //
        cda_manufacturedMaterial.code as cda_manufacturedMaterial_code where ($this.nullFlavor = 'NA') ->
          fhir_immunization.vaccineCode as fhir_immunization_vaccineCode,
          fhir_immunization_vaccineCode.extension as fhir_immunization_vaccineCode_extension then 
          CdaNullFlavorToFhirNullFlavor(cda_manufacturedMaterial_code, fhir_immunization_vaccineCode_extension); 

        // substanceAdministration/consumable/manufacturedProduct/manufacturedMaterial/code -> Immunization.vaccineCode
        //
        // TODO: nullFlavor-extension vs. dataAbsentReason-extension vs. nullFlavor-coding
        //
        cda_manufacturedMaterial.code as cda_manufacturedMaterial_code where ($this.nullFlavor = 'OTH') ->
          fhir_immunization.vaccineCode as fhir_immunization_vaccineCode,
          fhir_immunization_vaccineCode.extension as fhir_immunization_vaccineCode_extension then {
            cda_manufacturedMaterial_code then CdaNullFlavorToFhirNullFlavor(cda_manufacturedMaterial_code, fhir_immunization_vaccineCode_extension);

            cda_manufacturedMaterial_code.translation as cda_manufacturedMaterial_code_translation then CECodeableConcept(cda_manufacturedMaterial_code_translation, fhir_immunization_vaccineCode);
          };

        // substanceAdministration/consumable/manufacturedProduct/manufacturedMaterial/code -> Immunization.vaccineCode
        cda_manufacturedMaterial.code where ($this.nullFlavor.exists().not()) -> fhir_immunization.vaccineCode; 

        // substanceAdministration/consumable/manufacturedProduct/manufacturedMaterial/name
        //TODO

        // substanceAdministration/consumable/manufacturedProduct/manufacturedMaterial/lotNumberText -> Immunization.lotNumber
        cda_manufacturedMaterial.lotNumberText where ($this.nullFlavor.exists().not()) -> fhir_immunization.lotNumber;

        // substanceAdministration/consumable/manufacturedProduct/manufacturedMaterial/pharm:ingredient
        // TODO
      };

      // substanceAdministration/consumable/manufacturedProduct/manufacturerOrganization -> Immunization.manufacturer
      cda_manufacturedProduct.manufacturerOrganization as cda_manufacturerOrganization ->
        fhir_bundle.entry as fhir_bundle_entry,
        fhir_bundle_entry.resource = create('Organization') as fhir_organization,
        fhir_organization.id = uuid() as fhir_organization_id,
        fhir_bundle_entry.fullUrl = append('urn:uuid:', fhir_organization_id),
        fhir_immunization.manufacturer = create('Reference') as fhir_immunization_organization_reference,
        fhir_immunization_organization_reference.reference = append('urn:uuid:', fhir_organization_id),
        fhir_immunization_organization_reference.type = 'Organization' then
        CdaOrganizationCompilationToFhirOrganization(cda_manufacturerOrganization, fhir_organization);
    };
  };

    // cda_substanceAdministration.performer as cda_performer then {
    
    //   cda_performer -> fhir_bundle.entry as fhir_bundle_entry03,
    //   fhir_bundle_entry03.resource = create('PractitionerRole') as fhir_practitionerRole,
